import pandas as pd

def extract_close(df, tickers):
    if isinstance(df.columns, pd.MultiIndex):
        close = df["Close"][tickers]
    else:
        close = df[["Close"]].copy()
        close.columns = tickers
    close = close.dropna()
    if close.shape[0] == 0:
        raise ValueError("No usable price rows after dropna")
    return close
