def extract_quotes(multi_exec_resp):
    out = []
    for r in (multi_exec_resp.get('results') or []):
        d = ((r.get('response') or {}).get('data') or {})
        res = d.get('results') or {}
        summ = (res.get('summary') or {})
        out.append({'tool_index': r.get('index'), 'instrument': summ.get('stock') or summ.get('title'), 'extracted_price': summ.get('extracted_price')})
    return out
